select case when duration_sec >= 367 then 'high' when duration_sec >= 218 then 'mid' else 'low' end as duration_sec_bucket, round((100 * sum(case when event_type = 'page_view' then 1 else 0 end)) / count(*), 1) as pct_page_view, concat_ws(', ', sort_array(collect_set(page))) as page_values, round(avg(duration_sec), 2) as avg_duration_sec from web_events where session_id = 24 and duration_sec <= 197 group by case when duration_sec >= 367 then 'high' when duration_sec >= 218 then 'mid' else 'low' end order by pct_page_view desc
